"""Selectable multi-product rank lines over one platform/market/chart."""

CSS = r'''
.compare-panel{border:1px solid var(--line);border-radius:10px;background:var(--white);padding:20px;margin:20px 0}.compare-panel h3{font-size:20px;margin:0 0 6px}.compare-description{font-size:13px;color:#43584c;line-height:1.8}.compare-layout{display:grid;grid-template-columns:270px minmax(0,1fr);gap:22px;margin-top:14px}.compare-picker{min-width:0;border:1px solid var(--line);border-radius:8px;padding:12px;margin:0;align-self:start}.compare-picker legend{padding:0 5px;font-size:14px;font-weight:650}.compare-search input{width:100%;min-height:38px}.compare-actions{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0}.compare-actions button{font:inherit;font-size:12px;border:1px solid var(--line);border-radius:5px;background:#f3f6f0;color:var(--green);padding:6px 9px}.compare-choices{max-height:290px;overflow-y:auto;padding-right:4px}.compare-choice{display:flex;align-items:flex-start;gap:8px;cursor:pointer;color:var(--ink);font-size:13px;line-height:1.6;padding:8px 3px;border-bottom:1px solid #edf2ed}.compare-choice input{width:18px;height:18px;min-height:18px;flex:0 0 18px;accent-color:var(--green);margin:2px 0 0}.compare-choice input:disabled+span{opacity:.55}.compare-choice .compare-choice-name{display:block;overflow-wrap:anywhere}.compare-choice small{display:block;color:var(--muted);font-size:11px}.compare-choice:has(input:checked){background:#f0f7f2}.compare-count{font-size:12px;color:#43584c;margin:8px 0;line-height:1.7}.compare-visual{min-width:0}.compare-toolbar{display:flex;flex-wrap:wrap;gap:10px;margin-bottom:7px}.compare-toolbar select{max-width:100%;padding:7px 9px;min-height:38px}.compare-chart svg{width:100%;height:auto;display:block;overflow:visible}.compare-chart [role=button]{cursor:pointer}.compare-chart [role=button]:focus{outline:2px solid #153d30;outline-offset:3px}.compare-legend{display:flex;gap:7px 12px;flex-wrap:wrap;margin:10px 0;font-size:12px;line-height:1.7}.compare-legend-item{display:inline-flex;align-items:center;gap:6px;overflow-wrap:anywhere}.compare-swatch{display:inline-block;flex:0 0 24px;width:24px;border-top:3px solid}.compare-readout{padding:10px 12px;border-radius:6px;background:#edf2ed;margin-top:10px;font-size:12px;line-height:1.8}.compare-readout strong{display:block;font-size:13px}.compare-readout-list{display:flex;flex-wrap:wrap;gap:4px 16px}.compare-gap-details{font-size:12px;color:#43584c;margin:10px 0;line-height:1.8}.compare-gap-details summary{cursor:pointer;color:var(--green)}.compare-gap-details ul{margin:6px 0}.compare-empty{padding:50px 16px;background:#f3f6f0;border-radius:8px;color:var(--muted);font-size:14px;text-align:center}.compare-help{font-size:12px;color:var(--muted);margin-top:12px;line-height:1.8}
@media(max-width:900px){.compare-layout{grid-template-columns:1fr;gap:16px}.compare-choices{max-height:190px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 10px}.compare-picker{padding:10px}.compare-panel{padding:14px}.compare-actions{margin:8px 0}.compare-choice{font-size:12px}.compare-toolbar label{min-width:115px;flex:1}}
'''

HTML = r'''
<section class="compare-panel" aria-labelledby="compare-title"><h3 id="compare-title" tabindex="-1">05 · 这些产品每天如何变化</h3><p class="compare-description">每条线代表一款 App。横轴是日期，纵轴是榜单排名，第1名在顶部；线向上表示排名变好。勾选产品进行对比。</p><p id="compare-context" class="compare-count"></p><div class="compare-layout"><details class="compare-products" id="compare-products"><summary>更换对比产品 · 最多10款</summary><fieldset class="compare-picker"><legend>勾选对比产品</legend><label class="compare-search">查找候选产品<input id="compare-query" type="search" placeholder="名称或商店ID…"></label><div class="compare-actions"><button type="button" id="compare-first">选择名单前5款</button><button type="button" id="compare-clear">清空选择</button></div><p id="compare-count" class="compare-count" aria-live="polite"></p><div id="compare-choices" class="compare-choices"></div></fieldset></details><div class="compare-visual"><div class="compare-toolbar"><label>纵轴范围<select id="compare-scale"><option value="fit">按所选产品适配</option><option value="100">完整前100名</option></select></label><label>查看某日名次<select id="compare-date"></select></label></div><p id="compare-axis-note" class="compare-count"></p><div id="compare-chart" class="compare-chart"></div><div id="compare-legend" class="compare-legend" aria-label="线条与产品对应关系"></div><div id="compare-readout" class="compare-readout" role="status" aria-live="polite"></div><details id="compare-gap-details" class="compare-gap-details"><summary id="compare-gap-summary"></summary><ul id="compare-gaps"></ul></details></div></div><p class="compare-help">默认按当前产品名单顺序选择前5款，最多同时对比10款。也可从“排名上升或下降”图一键带入前5款。此图始终展示排名，下方表格可独立切换评分指标。缺失日期不连线、不补成0或第100名；点击数据点或用键盘聚焦后按回车，可查看当天名次。</p></section>
'''

JS = r'''
const comparePalette=['#176f53','#285ca8','#a95820','#874296','#b03358','#187884','#80620e','#514795','#6d5347','#8b3f20'];
const compareDashes=['','7 4','2 4','10 3 2 3','12 5','','7 4','2 4','10 3 2 3','12 5'];
const compareScopes=new Map();let compareContext={cohort:[],dates:[],kind:'free',label:'',key:''},compareState=null,compareDrawWidth=0;
function compareStyle(id){const used=new Set([...compareState.selected].filter(k=>k!==id).map(k=>compareState.slots.get(k)).filter(Number.isInteger));let slot=compareState.slots.get(id);if(!Number.isInteger(slot)||used.has(slot)){slot=comparePalette.findIndex((_,i)=>!used.has(i));compareState.slots.set(id,slot);}return {slot,color:comparePalette[slot],dash:compareDashes[slot]};}
function compareSelected(){return compareContext.cohort.filter(p=>compareState?.selected.has(p.app_id));}
function compareLineSwatch(style){const swatch=node('i',null,'compare-swatch');swatch.style.borderColor=style.color;swatch.style.borderTopStyle=style.dash?(style.dash==='2 4'?'dotted':'dashed'):'solid';swatch.setAttribute('aria-hidden','true');return swatch;}
function renderCompareChoices(focusId){el('compare-context').textContent=compareContext.label+' · '+(compareContext.poolLabel||'期间曾上过榜')+' · 候选'+compareContext.cohort.length+'款，当前勾选'+compareState.selected.size+'款，每款画一条线。';const host=el('compare-choices'),scroll=host.scrollTop,q=el('compare-query').value.trim().toLowerCase();host.replaceChildren();const candidates=compareContext.cohort.filter(p=>!q||[p.name,p.app_id].join(' ').toLowerCase().includes(q));for(const p of candidates){const label=node('label',null,'compare-choice'),input=node('input'),text=node('span'),name=node('span',p.name,'compare-choice-name');input.type='checkbox';input.value=p.app_id;input.checked=compareState.selected.has(p.app_id);input.disabled=!input.checked&&compareState.selected.size>=10;input.setAttribute('aria-label','对比 '+p.name);const latest=p.observations.find(r=>r.date===data.as_of);text.append(name,node('small','报告当日 '+(latest?rankState(latest,compareContext.kind):'观测缺失')));label.append(input,text);host.append(label);input.addEventListener('change',()=>{if(input.checked&&compareState.selected.size>=10&&!compareState.selected.has(p.app_id)){input.checked=false;return;}if(input.checked)compareState.selected.add(p.app_id);else compareState.selected.delete(p.app_id);compareSelected().forEach(v=>compareStyle(v.app_id));renderCompareChoices(p.app_id);renderComparePlot();});if(p.app_id===focusId)input.focus({preventScroll:true});}if(!candidates.length)host.append(node('p','没有匹配的候选产品。','sub'));host.scrollTop=scroll;el('compare-count').textContent='已选'+compareState.selected.size+'款 / 最多10款 · 候选'+compareContext.cohort.length+'款'+(q?'，搜索匹配'+candidates.length+'款':'');}
function inspectCompareDate(day){if(!compareContext.dates.includes(day))return;el('compare-date').value=day;renderCompareReadout();}
function renderCompareReadout(){const ps=compareSelected(),day=el('compare-date').value;el('compare-readout').replaceChildren();if(!ps.length){el('compare-readout').textContent='勾选产品后，选择日期即可查看各款 App 当天的准确名次。';return;}el('compare-readout').append(node('strong',day+' · 当天各产品排名'));const list=node('div',null,'compare-readout-list');for(const p of ps){const r=p.observations.find(r=>r.date===day),style=compareStyle(p.app_id);list.append(node('span',(style.slot+1)+'. '+p.name+'：'+(r?rankState(r,compareContext.kind):'观测缺失')));}el('compare-readout').append(list);}
function renderCompareGaps(ps){el('compare-gaps').replaceChildren();let affected=0;for(const p of ps){let hasGap=false;for(const [state,reason]of Object.entries(rankReasons)){const days=compareContext.dates.filter(day=>{const r=p.observations.find(r=>r.date===day);return !r?state==='missing':!numberValue(r[compareContext.kind+'_rank'])&&r[compareContext.kind+'_status']===state;});if(days.length){hasGap=true;el('compare-gaps').append(node('li',p.name+' · '+describeDates(days)+'：'+reason+'；该处折线断开。'));}}if(hasGap)affected++;}el('compare-gap-summary').textContent=affected?'断线说明 · '+affected+'款产品有无值日期（展开查看）':ps.length?'已选产品在本窗口均有逐日排名，没有断线。':'尚未选择产品。';el('compare-gap-details').hidden=!affected;}
function renderComparePlot(){const host=el('compare-chart'),legend=el('compare-legend');host.replaceChildren();legend.replaceChildren();const ps=compareSelected(),dates=compareContext.dates,kind=compareContext.kind;renderCompareReadout();renderCompareGaps(ps);if(!ps.length||!dates.length){host.append(node('p',compareContext.cohort.length?'请勾选要对比的产品，每条线对应一款 App。':'当前榜单没有可供对比的产品。','compare-empty'));el('compare-axis-note').textContent='横轴：日期；纵轴：排名。';return;}
const values=ps.flatMap(p=>dates.map(day=>p.observations.find(r=>r.date===day)?.[kind+'_rank'])).filter(numberValue);if(!values.length){host.append(node('p','所选产品在本窗口没有排名记录，原因见断线说明。','compare-empty'));return;}
const ymax=el('compare-scale').value==='100'?100:Math.min(100,Math.max(10,Math.ceil(Math.max(...values)/10)*10));el('compare-axis-note').textContent='实际日期：'+dates[0]+' 至 '+dates[dates.length-1]+'（'+dates.length+'天） · 当前纵轴：第1—'+ymax+'名'+(el('compare-scale').value==='fit'?'，按所选产品范围适配':'，固定完整前100名')+'。';
const ns='http://www.w3.org/2000/svg',W=Math.max(280,Math.round(host.clientWidth||700)),H=W<450?320:350,L=53,R=20,T=36,B=55,xx=i=>L+(dates.length===1?(W-L-R)/2:i*(W-L-R)/(dates.length-1)),yy=v=>T+(v-1)/(ymax-1)*(H-T-B),svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.setAttribute('role','group');svg.setAttribute('aria-label','多产品排名对比：横轴日期，纵轴名次，第1名在顶部');svg.dataset.ymax=ymax;
function shape(tag,attrs,text,parent=svg){const n=document.createElementNS(ns,tag);for(const [k,v]of Object.entries(attrs))n.setAttribute(k,String(v));if(text!==undefined)n.textContent=text;parent.append(n);return n;}
shape('text',{x:L,y:17,'font-size':12,fill:'#43584c'},'纵轴：榜单排名（第1名在上方）');shape('text',{x:(L+W-R)/2,y:H-7,'text-anchor':'middle','font-size':12,fill:'#43584c'},'横轴：日期（月-日）');let ticks=ymax===10?[1,5,10]:ymax===20?[1,5,10,15,20]:ymax===100?[1,25,50,75,100]:[1,...Array.from({length:Math.floor(ymax/10)},(_,i)=>(i+1)*10)];for(const v of ticks){const y=yy(v);shape('line',{x1:L,y1:y,x2:W-R,y2:y,stroke:'#d8e3dc'});shape('text',{x:L-8,y:y+4,'text-anchor':'end','font-size':12,fill:'#43584c'},'#'+v);}const indices=dates.length<=10&&W>650?dates.map((_,i)=>i):[0,Math.floor((dates.length-1)/2),dates.length-1];for(const i of [...new Set(indices)])shape('text',{x:xx(i),y:H-B+23,'text-anchor':'middle','font-size':12,fill:'#43584c'},dates[i].slice(5));
for(const p of ps){const style=compareStyle(p.app_id),g=shape('g',{'data-app-id':p.app_id,'data-color':style.color,'aria-label':p.name});let part=[];function flush(){if(part.length>1)shape('polyline',{points:part.join(' '),fill:'none',stroke:style.color,'stroke-width':2.5,'stroke-dasharray':style.dash||'none'},undefined,g);part=[];}dates.forEach((day,i)=>{const r=p.observations.find(r=>r.date===day),v=r?.[kind+'_rank'];if(!numberValue(v)){flush();return;}part.push(xx(i)+','+yy(v));});flush();dates.forEach((day,i)=>{const r=p.observations.find(r=>r.date===day),v=r?.[kind+'_rank'];if(!numberValue(v))return;const dot=shape('circle',{cx:xx(i),cy:yy(v),r:4,fill:style.color,stroke:'#fff','stroke-width':1,tabindex:0,role:'button','data-date':day,'data-value':v,'aria-label':p.name+'，'+day+'，第'+v+'名，按回车查看当天排名'},undefined,g);shape('title',{},p.name+' · '+day+' · 第'+v+'名',dot);dot.addEventListener('click',()=>inspectCompareDate(day));dot.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();inspectCompareDate(day);}});});const item=node('span',null,'compare-legend-item');item.dataset.appId=p.app_id;item.append(compareLineSwatch(style),node('span',(style.slot+1)+'. '+p.name));legend.append(item);}host.append(svg);}
function updateRankComparison(cohort,dates,context){const key=[context.platform,context.country,context.kind,context.pool||'today',context.statusFilter||'all'].join('|'),changed=key!==compareContext.key;compareContext={cohort,dates,...context,key};if(!compareScopes.has(key))compareScopes.set(key,{selected:new Set(cohort.slice(0,5).map(p=>p.app_id)),slots:new Map()});compareState=compareScopes.get(key);const ids=new Set(cohort.map(p=>p.app_id));compareState.selected=new Set([...compareState.selected].filter(id=>ids.has(id)));compareSelected().forEach(p=>compareStyle(p.app_id));if(changed)el('compare-query').value='';const old=el('compare-date').value;el('compare-date').replaceChildren();for(const day of dates){const option=node('option',day);option.value=day;el('compare-date').append(option);}el('compare-date').value=dates.includes(old)?old:(dates[dates.length-1]||'');el('compare-context').textContent=context.label+' · '+(context.poolLabel||'报告当日在榜')+' · 当前展示范围'+(context.limitLabel||el('overview-limit').value+'款')+'（实际'+cohort.length+'款），仅在同一平台、市场和榜单内比较。';renderCompareChoices();renderComparePlot();}
el('compare-query').addEventListener('input',()=>renderCompareChoices());el('compare-clear').addEventListener('click',()=>{compareState.selected.clear();renderCompareChoices();renderComparePlot();});el('compare-first').addEventListener('click',()=>{compareState.selected=new Set(compareContext.cohort.slice(0,5).map(p=>p.app_id));compareSelected().forEach(p=>compareStyle(p.app_id));el('compare-query').value='';renderCompareChoices();renderComparePlot();});el('compare-scale').addEventListener('change',renderComparePlot);el('compare-date').addEventListener('change',renderCompareReadout);
if(typeof ResizeObserver!=='undefined'){const compareResize=new ResizeObserver(entries=>{const width=Math.round(entries[0].contentRect.width);if(width>0&&width!==compareDrawWidth){compareDrawWidth=width;renderComparePlot();}});compareResize.observe(el('compare-chart'));}
'''
